cd "$INPUT_DIR" && python3 -c "
import openpyxl,glob
for f in sorted(glob.glob('*.xlsx')):
    wb=openpyxl.load_workbook(f,data_only=True)
    for ws in wb:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value,str) and ('ristol' in c.value or 'lasgow' in c.value or 'site' in c.value.lower() or 'Leeds' in c.value):
                    print(f,'|',ws.title,'|',c.coordinate,'|',repr(c.value)[:160])
"
echo '--- csv header ---'
head -3 "$INPUT_DIR/Order Line Extract - May-26.csv"

cd "$INPUT_DIR" && for f in *.pptx; do echo "=== $f ==="; python3 -c "
from pptx import Presentation
import sys
p=Presentation(sys.argv[1])
for i,s in enumerate(p.slides,1):
    for sh in s.shapes:
        if sh.has_text_frame and sh.text_frame.text.strip():
            print(i,'|',sh.text_frame.text.replace(chr(10),' / ')[:400])
        if sh.has_table:
            for r in sh.table.rows:
                print(i,'|TBL|',' | '.join(c.text for c in r.cells)[:300])
" "$f"; done

